import os, json, glob, time, re, collections
root=os.path.expanduser('~/.claude/projects')
cut=time.time()-60*86400
files=[f for f in glob.glob(root+'/**/*.jsonl',recursive=True) if os.path.getmtime(f)>=cut]
print('files',len(files))
skill=collections.Counter(); slash=collections.Counter(); runner=collections.Counter(); hits=collections.defaultdict(list)
pat=re.compile(r'<command-name>/?(codex-review|claudex-loop|claudex-route|codex-build)</command-name>')
for f in files:
    try:
        for line in open(f,errors='ignore'):
            if 'codex-review' not in line and 'claudex' not in line and 'codex-build' not in line: continue
            try: d=json.loads(line)
            except: continue
            ts=d.get('timestamp','')
            msg=d.get('message',{})
            c=msg.get('content') if isinstance(msg,dict) else None
            if isinstance(c,list):
                for it in c:
                    if isinstance(it,dict) and it.get('type')=='tool_use':
                        inp=it.get('input',{})
                        if it.get('name')=='Skill':
                            s=inp.get('skill','')
                            if s in('codex-review','claudex-loop','claudex-route','codex-build'):
                                skill[s]+=1; hits[s].append((ts[:10],f.split('/projects/')[1][:90]))
                        if it.get('name')=='Bash' and 'runner.py' in str(inp.get('command','')) and 'claudex' in str(inp.get('command','')):
                            runner[ts[:10]]+=1
            text=json.dumps(c) if c is not None else ''
            if d.get('type')=='user':
                for m in pat.findall(text):
                    slash[m]+=1; hits['/'+m].append((ts[:10],f.split('/projects/')[1][:90]))
    except Exception as e: pass
print('Skill tool',dict(skill)); print('slash',dict(slash)); print('runner bash calls by day',dict(runner))
for k,v in hits.items():
    print(k); [print('  ',x) for x in sorted(set(v))[:15]]

